import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"雷地豫","description":"周易折中 - 雷地豫","frontmatter":{"title":"雷地豫","description":"周易折中 - 雷地豫"},"headers":[],"relativePath":"zh/classics/zhezhong/022.md","filePath":"zh/classics/zhezhong/022.md"}'),h={name:"zh/classics/zhezhong/022.md"};function n(p,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="雷地豫" tabindex="-1">雷地豫 <a class="header-anchor" href="#雷地豫" aria-label="Permalink to “雷地豫”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>豫序卦：“有大而能谦，必豫，故受之以豫。”承二卦之义而为次也。有既大而能谦，则有豫乐也。豫者，安和悦乐之义。为卦震上坤下，顺动之象，动而和顺，是以豫也。九四为动之主，上下群阴所共应也，坤又承之以顺，是以动而上下顺应，故为和豫之义。以二象言之，雷出于地上，阳始濳闭于地中，及其动而出地，奋发其声，通畅和豫，故为豫也。</p><p>豫：利建侯行师</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>豫，和乐也。人心和乐以应其上，九四一阳上下应之，其志得行。又以坤遇震，为顺以动，故其卦为豫，而其占利以立君用师也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>豫，顺而动也。豫之义所利，在于建侯行师。夫建侯树屏，所以共安天下，诸侯和顺，则万民悦服。兵师之兴，众心和悦，则顺从而有功。故悦豫之道，利于建侯行师也。又上动而下顺，诸侯从王，师众顺令之象，君万邦聚大众，非和悦不能使之服从也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰 ：谓之豫者，取逸豫之义。以和顺而动，动不违众，众皆悦豫，故谓之豫也。动而众悦，故利建侯；以顺而动，故可以行师也。</p></li><li><p>邱氏富国曰 ：屯有震无坤，则言建侯而不言行师；谦有坤无震，则言行师而不言建侯。此合震坤成卦，故兼之。</p></li></ul><p>象曰：雷出地奋，豫；先王以作乐崇德，殷荐之上帝，以配祖考</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>雷出地奋，和之至也。先王作乐，既象其声，又取其义，殷盛也。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>雷者，阳气奋发，阴阳相薄而成声也。阳始潜闭地中，及其动则出地奋震也。始闭郁及奋发则通畅和豫，故为豫也。坤顺震发，和顺积中而发于声乐之象也。先王观雷出地而奋，和畅发于声之象，作声乐以褒崇功德，其殷盛至于荐之上帝，推配之以祖考，殷盛也。礼有殷奠，谓盛也。荐上帝配祖考，盛之至也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>荀氏爽曰 ：乐者，圣人因人之豫而节之，所以养其正而闲其邪。其和可以感鬼神，而况于人乎？</p></li><li><p>郑氏康成曰 ：奋动也。雷动于地上，万物乃豫也。人至乐，则手欲鼓之，足欲舞之。王者功成作乐，以文得之者作龠舞，以武得之者作万舞，各充其德而为制。祀天帝以配祖考者，使与天同飨其功也。故《孝经》云：“郊祀后稷以配天，宗祀文王于明堂以配上帝”也。</p></li><li><p>胡氏炳文曰 ：本义云“象其声者”，乐之声法雷之声；“又取其义者”，豫以和为义。雷所以发扬化功而鼓天地之和，乐所以发扬功德而召神人之和也。</p></li></ul><p>彖曰：豫，刚应而志行，顺以动，豫</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦体卦德释卦名义。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>刚应谓四为群阴所应，刚得众应也。志行谓阳志上行动，而上下顺从其志，得行也。顺以动豫，震动而坤顺，为动而顺，顺理而动，又为动而众顺，所以豫也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰：建万国，聚大众，非顺理而动，使人心皆和乐而从，不可也。故二者皆系之豫。案彖传中凡称卦德，皆先内而后外，而其文义又各不同。其曰“而”者，两字并重，如讼之“险而健”，既险又健也；小畜之“健而巽”，既健又巽也；大有“刚健而文明”，既刚健而又文明也。其曰“以”者，则重在上一字，如同人“文明以健”，重在“文明”字。此卦“顺以动”，重在“顺”字。其或以下一字为重者，则又变其文法，如复卦“动而以顺行”之类。</li></ul><p>豫，顺以动，故天地如之，而况建侯行师乎</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以卦德释卦辞。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>以豫顺而动，则天地如之而弗违，况建侯行师，岂有不顺乎？天地之道，万物之理，惟至顺而已。大人所以先天后天而不违者，亦顺乎理而已。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li>呉氏曰愼曰：顺以动，所谓行其所无事也。天地如之，犹云天且弗违。得其民者得其心也，故豫利建侯。多助之至，天下顺之，故豫利行师。</li></ul><p>天地以顺动，故日月不过，而四时不忒；圣人以顺动，则刑罚清而民服。豫之时义大矣哉</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>极言之而赞其大也。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>复详言顺动之道。天地之运，以其顺动，所以日月之度不过差，四时之行不愆忒。圣人以顺动，故经正而民兴于善，刑罚清简而万民服也。既言豫顺之道矣，然其旨味渊永，言尽而意有馀也，故复赞之云：“豫之时义大矣哉”，欲人研味其理，优柔涵泳而识之也。时义谓豫之时义，诸卦之时与义用大者，皆赞其大矣哉。豫以下十一卦是也。豫、遁、姤、旅言时义，坎、睽、蹇言时用，颐、大过、解、革言时，各以其大者也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>项氏安世曰：豫、随、遁、姤、旅皆若浅事而有深意，故曰时义大矣哉，欲人之思之也。坎、睽、蹇皆非美事，而圣人有时而用之，故曰时用大矣哉，欲人之别之也。颐、大过、解、革皆大事大变也，故曰时大矣哉，欲人之谨之也。</p></li><li><p>呉氏澄曰：专言时者，重在时字；时义，重在义字；时用，重在用字。</p></li><li><p>蔡氏清曰：时之一字，贯六十四卦皆有，不止豫等诸卦耳。有时则有义，有义则有用。单言时，则义与用在其中矣。言义未尝无用，言用未尝无义，各就所切而言。</p></li></ul><p>初六：鸣豫凶。</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>阴柔小人上有强援，得时主事，故不胜其豫而以自鸣凶之道也。故其占如此卦之得名本为和乐，然卦辞为众乐之义。爻辞除九四与卦同外，皆为自乐，所以有吉凶之异。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>初六以阴柔居下，四豫之主也，而应之是不中正之小人处，豫而为上所宠，其志意满极不胜其豫，至发于声音轻浅，如是必至于凶也。鸣发于声也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>石氏介曰：四为豫之主，初与之相应，小人得志必极其情欲以至于凶，形于声鸣，豫之甚也。</p></li><li><p>苏氏轼曰：所以为豫者四也，而初和之，故曰鸣已无以自乐，而恃其配以为乐，不得不凶。</p></li><li><p>王氏应麟曰：鸣谦则吉，鸣豫则凶，鸣者心声之发也。</p></li><li><p>龚氏焕曰：豫之初六即谦上六之反对，故谦上六曰鸣谦，豫初六曰鸣豫，谦之上六应九三，故鸣其谦豫之初六，应九四，故不胜其豫以自鸣，谦而鸣则吉，豫而鸣则凶。</p></li></ul><p>象曰：初六鸣豫，志穷凶也</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>穷谓满极。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>初六谓其以阴柔处下而志意穷极，不胜其豫，至于鸣也，必骄肆而致凶矣。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>杨氏简曰 ：位之在下，未为穷也。豫而鸣，其志穷矣。</p></li><li><p>赵氏汝梅曰 ：位方在初，时势未穷而竞躁如此，是志已先穷，自取其凶者也。</p></li></ul><p>六二：介于石，不终日，贞吉。</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>豫虽主乐，然易以溺人，溺则反而忧矣。卦独此爻中而得正，是上下皆溺于豫，而独能以中正自守，其介如石也。其德安静而坚确，故其思虑明审，不俟终日而见凡事之几微也。大学曰，安而后能虑，虑而后能得意，正如此占者如是则正而吉矣。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>逸豫之道放则失正，故豫之诸爻多不得正才与时合也。惟六二一爻处中正，又无应为自守之象，当豫之时独能以中正自守，可谓特立之操，是其节介如石之坚也。介于石，其介如石也。人之于豫乐心悦之故，迟迟遂至于耽恋，不能已也。二以中正自守，其介如石，其去之速，不俟终日，故贞正而吉也。处豫不可安且久也，久则溺矣。如二可谓见几而作者也。夫子因二之见几而极言知几之道，曰，知几其神乎。君子上交不谄，下交不渎，其知几乎。几者动之微，吉之先见者也。君子见几而作，不俟终日。易曰，介于石，不终日，贞吉。介如石，焉宁用终日断可识矣。君子知微，知彰，知柔，知刚，万夫之望。夫见事之几微者，其神妙矣乎。君子上交不至于谄，下交不至于渎者，盖知几也。不知几则至于过而不已，交于上以恭巽，故过则为谄，交于下以和易，故过则为渎。君子见于几微，故不至于过也。所谓几者，始动之微也，吉凶之端可先见而未著者也。独言吉者，见之于先，岂复至有凶也。君子明哲，见事之几微，故能其介如石，其守既坚，则不惑而明，见几而动，岂俟终日也，断别也，其判别可见矣。微与彰，柔与刚，相对者也。君子见微则知彰矣，见柔则知刚矣。知几如是，众所仰也，故赞之曰，万夫之望。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏宗传曰：凡人之情于逸豫之事，心焉悦之，必至于耽恋而不舍，何者有所溺故也。惟知几之君子，其视乐豫之事，如将浼已，断而识之速而去之，又岂俟终日也哉。此其所以当豫之时而获吉也。</p></li><li><p>丘氏富国曰：豫诸爻以无所系应者为吉，豫初应四而三五比四皆有系者也，是以为凶，为悔，为疾。独六二阴静而中正，与四无系，特立于众阴之中，而无迟迟耽恋之意，方其静也则确然自守，而介于石。及其动也则见几而作，不俟终日，盖其所居得正，故动静之闲不失其正，吉可知矣。</p></li></ul><p>象曰：不终日贞吉，以中正也</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>能不终日而贞且吉者，以有中正之德也。中正故其守坚而能辨之早，去之速。爻言六二处豫之道，为教之意深矣。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>黄氏淳耀曰 ：中正即介石意，是推明所以不终日之故。</li></ul><p>六三：盱豫，悔迟，有悔。</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>盱上视也，阴不中正而近于四，四为卦主，故六三上视于四而下溺于豫，宜有悔者也。故其象如此，而其占为事当速悔，若悔之迟，则必有悔也。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>六三阴而居阳，不中不正之人也，以不中正而处豫，动皆有悔。盱上视也，上瞻望于四，则以不中正不为四所取，故有悔也。四豫之主与之切近，苟迟迟而不前，则见弃绝，亦有悔也。盖处身不正，进退皆有悔吝，当如之何，在正身而已。君子处已有道以礼制心，虽处豫时不失中正，故无悔也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郭氏忠孝曰：处豫之道，戒在不能自立而优游无断，睢盱上视而悦之，非介于石者也，迟疑而有待，非不终日者也。</p></li><li><p>胡氏炳文曰：二中而得正，三阴不中正，故盱豫与介石相反，迟与不终日相反，中正与不中正故也。六三虽柔其位，阳犹有能悔之意，然悔之速可也，悔之迟则又必有悔矣。</p></li></ul><p>象曰：盱豫有悔，位不当也</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>自处不当，失中正也，是以进退有悔。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏申子曰 ：此爻与六二相反，盱则不能介于石，迟则不能不终日，中正与不中正故也。</li></ul><p>九四：由豫大有得，勿疑朋盍簪。</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>九四卦之所由以为豫者也，故其象如此，而其占为大有得。然又当至诚不疑，则朋类合而从之矣。故又因而戒之，簪聚也，又速也。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>豫之所以为豫者由九四也，为动之主，动而众阴悦顺，为豫之义。四大臣之位，六五之君顺从之以阳刚而任上之事，豫之所由也。故云由豫大有得，言得大行其志以致天下之豫也。勿疑朋盍簪，四居大臣之位，承柔弱之君而当天下之任，危疑之地也。独当上之倚任，而下无同德之助，所以疑也。唯当尽其至诚，勿有疑虑，则朋类自当盍聚。欲上下之信，唯至诚而已。苟尽其至诚，则何患乎其无助也。簪聚也，簪之名簪取聚发也。或曰，卦唯一阳，安得同德之助。曰，居上位而至诚求助，理必得之。姤之九五曰，有陨自天，是也。四以阳刚迫近君位，而专主乎豫，圣人宜为之戒，而不然者，豫和顺之道也。由和顺之道，不失为臣之正也。如此而专主于豫，乃是任天下之事，而致时于豫者也。故唯戒以至诚，勿疑。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>侯氏行果曰：为豫之主，众阴所宗，莫不由之以得其逸体，刚心直志，不怀疑，故得群物依归，朋从大合，若以簪篸之固括也。</p></li><li><p>耿氏南仲曰：九四为震之主，以象言之，万物莫不由雷以豫，以爻言之，五阴莫不由阳以豫，是以大有得也。大有得而勿疑，乃能协众力以安其上，犹簪之总众发以安其冠，若自疑则众斯睽矣，未闻疑事而有功者也。</p></li><li><p>梁氏寅曰：由豫者，言人心之和豫由四而致也，处近君之地以刚而能柔，众阴之所顺附，此所谓大有得也。然人既乐从，则当开诚心布公道，待以旷大之度，不为物我之私，然后有以致人心之皆服，故曰勿疑朋盍簪。</p></li><li><p>蔡氏清曰：九四由豫大有得矣，又必戒以勿疑朋盍簪，者诚以由豫任大责重，难以独力，必得同德者以自辅。自古以圣哲之资而居元臣之任者如舜，则举八元八凯，伊尹周公，皆有俊乂吉人之助。诸葛孔明亦必开诚心以来诸贤之益，圣人命辞之意深矣哉。</p></li><li><p>何氏楷曰：簪聚也，簪之名簪取聚髪也。或谓古冠服无簪，按盐铁论神禹治水遗簪不顾，非簪而何，即弁服之笄是也。</p></li></ul><p>象曰：由豫大有得，志大行也</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>由己而致天下于乐豫，故为大有得，谓其志得大行也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>乔氏中和曰 ：刚应而志行，盖由四以阳刚为群阴所应，故其志得以大行也。</li></ul><p>六五：贞疾恒不死。</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>当豫之时以柔居尊，沈溺于豫，又乘九四之刚，众不附而处势危，故为贞疾之象。然以其得中，故又为常不死之象，即象而观占在其中矣。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>六五以阴柔居君位，当豫之时沈溺于豫，不能自立者也。权之所主，众之所归，皆在于四，四之阳刚得众，非耽惑柔弱之君所能制也。乃柔弱不能自立之君，受制于专权之臣也。居得君位贞也，受制于下有疾苦也。六五尊位权虽失，而位未亡也，故云贞疾恒不死，言贞而有疾，常疾而不死，如汉魏末世之君也。人君致危亡之道非一，而以豫为多，在四不言失正，而于五乃见其强逼者。四本无失故，在四言大臣任天下之事之义，在五则言柔弱居尊不能自立，威权去巳之义，各据爻以取义，故不同也。若五不失君道而四主于豫，乃是任得其人，安享其功如太甲成王也。䝉亦以阴居尊位，二以阳为䝉之主，然彼吉而此疾者时不同也。童蒙而资之于人宜也，耽豫而失之于人危亡之道也。故蒙相应则倚任者也，豫相逼则失权者也，又上下之心专归于四也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏宗传曰：当逸豫之时恣骄侈之欲，宜其死于安乐有馀也。然乘九四之刚，恃以拂弼于巳，故得恒不死也。孟子曰，入则无法家拂士，出则无敌国外患者国恒亡，然后知生于忧患而死于安乐也。则六五之得九四得法家拂士也，故虽当豫之时不得以纵其所乐，唯不得以纵其所乐则恒不死宜也。夫当豫之时而不为豫者以正自守也，六二是也。当豫之时而不得豫者，见正于人也，六五是也。此豫之六爻惟六二六五所以不言豫焉。</p></li><li><p>何氏楷曰：六五以柔居尊，当豫之时易于沈溺，必战兢畏惕，常如疾病在身，乃得恒而不死，所谓生于忧患者也。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>王民何氏说深得爻义。</p><p>象曰：六五贞疾，乘刚也；恒不死，中未亡也</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>贞而疾，由乘刚为刚所逼也；恒不死，中之尊位未亡也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>杨氏时曰 ：居豫之时，无刚健之才，逸于豫者也。孟子曰：“入则无法家拂士，出则无敌国外患者，国常亡。”六五之乘刚，有法家拂士、敌国外患之谓也。左右救正之故，以正为疾，虽未能执其中而中未亡，则不死于安乐矣。故常不死。</p></li><li><p>郑氏汝谐曰 ：二与五皆不言豫，二静晦不为豫也，五乘刚不敢豫也。若人得一固疾，虽不快于己，亦足以久其生者，有戒心也。是以终未亡而常存。</p></li><li><p>胡氏炳文曰 ：豫最易以溺人。六二柔中且正，能不终日而去之；六五阴柔不正，未免溺于豫矣。犹得不死者，中未亡也。人莫不生于忧患而死于逸乐，以六五之中仅得不死，然则初之鸣、三之盱、上之冥，其不中者皆非生道矣。</p></li></ul><p>上六：冥豫成，有渝无咎。</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>以阴柔居豫极，为昏冥于豫之象。以其动体，故又为其事虽成而能有渝之象。戒占者如是则能补过而无咎，所以广迁善之门也。</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>上六阴柔非有中正之德，以阴居上不正也。而当豫极之时，以君子居斯时，亦当戒惧。况阴柔乎，乃耽肆于豫，昏迷不知反者也。在豫之终，故为昏冥已成也。若能有渝变，则可以无咎矣。在豫之终有变之义，人之失若能自变皆可以无咎。故冥豫虽已成，能变则善也。圣人发此义，所以劝善也，故更不言冥之凶，专言渝之无咎。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏应麟曰：冥于豫而勉其有渝，开迁善之门也。冥于升而勉其不息，回进善之机也。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>贞疾与成有渝两爻之义亦相为首尾，如人之耽于逸乐而不能节其饮食起居者，是致死之道也。苟使纵其欲而无病，则将一病不支而亡也无日矣。惟其常有疾也，故常能忧惧儆戒而得不死也。然所贵乎忧惧儆戒者，以其能改变尔向也。耽于逸乐昏冥而不悟，殆将习与性成矣。今乃一变所为，而节饮食愼起居，则可以复得其性命之理。岂独不死而已乎，故于五不言无咎，而于上言之所以终卦义而垂至戒也。</p><p>象曰：冥豫在上，何可长也</p><h3 id="程传-17" tabindex="-1">程传 <a class="header-anchor" href="#程传-17" aria-label="Permalink to “程传”">​</a></h3><p>昏冥于豫，至于终极，灾咎行及矣，其可长然乎？当速渝也。</p><h3 id="集说-16" tabindex="-1">集说 <a class="header-anchor" href="#集说-16" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>胡氏瑗曰 ：何可长者，言其悦豫过甚，至于情荡性冥而不知所止，是何可长如此乎？言能渝变则可以无咎也。</p></li><li><p>王氏申子曰 ：豫至于上极矣，极则不可以久，速渝可也。</p></li></ul>',116)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
